import React, { Component } from 'react';
import axios from 'axios';
import MyContext from '../contexts/MyContext';
import '../css/ReceptionComponent.css';

class Reception extends Component {
  static contextType = MyContext;

  constructor(props) {
    super(props);
    this.state = {
      tables: [
        { id: '01', name: 'Bàn 01', status: 'occupied', guests: 4, time: '18:30' },
        { id: '02', name: 'Bàn 02', status: 'empty', seats: 4 },
        { id: '03', name: 'Bàn 03', status: 'reserved', time: '19:30' },
        { id: '04', name: 'Bàn 04', status: 'occupied', guests: 2, time: '19:00' },
        { id: '05', name: 'Bàn 05', status: 'empty', seats: 6 },
        { id: '06', name: 'Bàn 06', status: 'empty', seats: 2 },
        { id: '07', name: 'Bàn 07', status: 'reserved', time: '20:00' },
        { id: '08', name: 'Bàn 08', status: 'empty', seats: 8 }
      ],
      bookings: [
        { name: 'Anh Minh', phone: '0901234xxx', detail: 'Bàn 03 • 4 Người', time: '18:30' },
        { name: 'Chị Hương', phone: '0988776xxx', detail: 'Bàn 07 • 6 Người', time: '20:00' },
        { name: 'Anh Hoàng', phone: '0912334xxx', detail: 'Bàn VIP 01 • 10 Người', time: '20:30' }
      ]
    };
  }

  render() {
    const { tables, bookings } = this.state;
    const totalTables = 24;
    const occupiedCount = 8;
    const reservedCount = 5;
    const emptyCount = 11;

    return (
      <div className="reception-container">
        <h3 className="reception-title">QUẢN LÝ LỄ TÂN & ĐẶT BÀN</h3>

        {/* 4 Thẻ thống kê tổng quan */}
        <div className="reception-stats-grid">
          <div className="reception-stat-card">
            <div className="reception-stat-title">Tổng số bàn</div>
            <div className="reception-stat-value">{totalTables} Bàn</div>
          </div>
          <div className="reception-stat-card">
            <div className="reception-stat-title">Bàn đang có khách</div>
            <div className="reception-stat-value" style={{ color: '#C62828' }}>{occupiedCount} Bàn</div>
          </div>
          <div className="reception-stat-card">
            <div className="reception-stat-title">Bàn đã đặt trước</div>
            <div className="reception-stat-value" style={{ color: '#F57F17' }}>{reservedCount} Bàn</div>
          </div>
          <div className="reception-stat-card">
            <div className="reception-stat-title">Bàn còn trống</div>
            <div className="reception-stat-value" style={{ color: '#2E7D32' }}>{emptyCount} Bàn</div>
          </div>
        </div>

        {/* Layout 2 cột chính */}
        <div className="reception-main-layout">
          
          {/* CỘT TRÁI: Sơ đồ bàn trực quan */}
          <div className="reception-left-section">
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
              <h4 style={{ margin: 0, color: '#4A2E2B' }}>Sơ Đồ Bàn Trực Quan</h4>
              <div style={{ fontSize: '12px', color: '#666', display: 'flex', gap: '15px' }}>
                <span> Trống</span>
                <span> Có khách</span>
                <span> Đặt đặt</span>
              </div>
            </div>

            <div className="table-grid">
              {tables.map(table => (
                <div key={table.id} className={`table-card ${table.status}`}>
                  <div style={{ fontWeight: 'bold', fontSize: '15px', marginBottom: '4px' }}>{table.name}</div>
                  {table.status === 'occupied' && (
                    <>
                      <div style={{ fontSize: '12px' }}>Có khách ({table.guests} người)</div>
                      <div style={{ fontSize: '11px', marginTop: '4px' }}>Vào lúc: {table.time}</div>
                    </>
                  )}
                  {table.status === 'empty' && (
                    <div style={{ fontSize: '12px' }}>Bàn Trống<div style={{ fontSize: '11px', marginTop: '4px' }}>{table.seats} ghế</div></div>
                  )}
                  {table.status === 'reserved' && (
                    <>
                      <div style={{ fontSize: '12px' }}>Đã đặt trước</div>
                      <div style={{ fontSize: '11px', marginTop: '4px' }}>Khách đến: {table.time}</div>
                    </>
                  )}
                </div>
              ))}
            </div>
          </div>

          {/* CỘT PHẢI: Lịch đặt bàn trong ngày */}
          <div className="reception-right-section">
            <h4 style={{ margin: '0 0 15px 0', color: '#4A2E2B' }}>Lịch Đặt Bàn Trong Ngày</h4>
            <div>
              {bookings.map((item, idx) => (
                <div key={idx} className="booking-item">
                  <div>
                    <div style={{ fontWeight: 'bold', fontSize: '14px', color: '#333' }}>{item.name} - {item.phone}</div>
                    <div style={{ fontSize: '12px', color: '#666', marginTop: '3px' }}>{item.detail}</div>
                  </div>
                  <div className="time-badge">{item.time}</div>
                </div>
              ))}
            </div>
          </div>

        </div>
      </div>
    );
  }
}

export default Reception;
